param([string]$BaseUrl="http://127.0.0.1:8000",[int]$ProjectId=1)
$ErrorActionPreference="Stop"
function S([string]$scope){Invoke-RestMethod -Method Post -Uri "$BaseUrl/api/v1/auth/local/demo-session" -ContentType "application/json" -Body (@{scope=$scope}|ConvertTo-Json -Compress)}
function P([string]$path,[hashtable]$body,[hashtable]$headers){Invoke-RestMethod -Method Post -Uri "$BaseUrl$path" -Headers $headers -ContentType "application/json" -Body ($body|ConvertTo-Json -Depth 12 -Compress)}
$hq=S hq;$agency=S agency;$client=S client;$hh=@{Authorization="Bearer $($hq.token)"};$ah=@{Authorization="Bearer $($agency.token)"};$ch=@{Authorization="Bearer $($client.token)"};$n=Get-Date -Format "yyyyMMddHHmmssfff";$root="/api/v1/factory-platform/projects/$ProjectId/proof-center";$a=P "$root/assets" @{asset_type="certificate";source_reference="CERT-$n";rights_reference="RIGHTS-$n";market_scope="GLOBAL";valid_until="2099-01-01"} $hh;$v=P "$root/assets/$($a.id)/versions" @{claim_manifest=@{claim="Verified capability scope"}} $hh;$v=P "$root/versions/$($v.id)/verify" @{expected_revision=$v.revision;reference="PROOF-VERIFY-$n"} $ah;$r=P "$root/versions/$($v.id)/releases" @{target="marketing-owner";handoff_manifest=@{page="service";website_published_automatically=$false};rollback_reference="PROOF-ROLLBACK-$n"} $hh;$r=P "$root/releases/$($r.id)/approve" @{expected_revision=$r.revision;reference="PROOF-APPROVE-$n"} $ah;$r=P "$root/releases/$($r.id)/acknowledge" @{expected_revision=$r.revision;reference="PROOF-RECEIPT-$n"} $ch;$w=Invoke-RestMethod "$BaseUrl$root" -Headers $hh;[pscustomobject]@{release_available=$r.available;availability=$w.availability.status;source_asset_mutated_directly=$w.contract.source_asset_mutated_directly;expired_asset_published=$w.contract.expired_asset_published;website_published_automatically=$w.contract.website_published_automatically;evidence_count=$w.evidence.Count}|ConvertTo-Json
